//! Measure the real-world lint corpus and ratchet the pin.
//!
//! ```text
//! jals-lint-metrics            # measure and report
//! jals-lint-metrics --pin      # measure and rewrite `real-world-lint.tsv`
//! jals-lint-metrics --check    # measure and fail on any count the pin does not allow
//! ```
//!
//! `--check` is the gate: a change that makes the analysis report *more* about code it was already
//! reporting on fails here, and one that makes it report less is a `--pin` away from being the new
//! baseline. The corpus itself is generated by `scripts/gen-real-world-corpus.sh`, which is the
//! only step that needs the network.

use std::path::PathBuf;
use std::process::ExitCode;

use jals_tests::lint_metrics::{LintMetrics, RealWorldProject};

const PIN: &str = "real-world-lint.tsv";

fn main() -> ExitCode {
    let check = std::env::args().any(|arg| arg == "--check");
    let pin = std::env::args().any(|arg| arg == "--pin");
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let corpus = root.join("sources/real-world");

    let registry = std::fs::read_to_string(root.join("corpus/real-world.toml"))
        .expect("corpus/real-world.toml is part of the repository");
    let projects = RealWorldProject::registry(&registry).expect("the registry is well formed");

    let mut roots = Vec::new();
    for project in &projects {
        let path = corpus.join(&project.name);
        if path.is_dir() {
            println!("{:<10} {}", project.name, path.display());
            roots.push(path);
        } else {
            eprintln!(
                "{:<10} not generated; run jals-tests/scripts/gen-real-world-corpus.sh",
                project.name
            );
        }
    }
    if roots.is_empty() {
        eprintln!("no corpus to measure");
        return ExitCode::from(2);
    }

    let measured = LintMetrics::measure(&roots);
    println!("files: {}", measured.files);
    for (rule, count) in &measured.counts {
        println!("{count:>6}  {rule}");
    }

    let pin_path = root.join(PIN);
    if pin {
        std::fs::write(&pin_path, measured.render()).expect("the pin is writable");
        println!("wrote {}", pin_path.display());
        return ExitCode::SUCCESS;
    }

    let Ok(text) = std::fs::read_to_string(&pin_path) else {
        eprintln!("no pin at {}; run with --pin first", pin_path.display());
        return ExitCode::from(2);
    };
    let pinned = LintMetrics::parse(&text).expect("the pin is well formed");
    let regressions = measured.regressions(&pinned);
    if regressions.is_empty() {
        println!("no rule reports more than the pin allows");
        return ExitCode::SUCCESS;
    }
    for line in &regressions {
        eprintln!("regression: {line}");
    }
    if check {
        ExitCode::from(1)
    } else {
        ExitCode::SUCCESS
    }
}
